#!/usr/bin/env node
// Regenerates config/isp-allowlist.json from live BGP data (RIPEstat).
//
// The Front Door WAF (infra/modules/frontdoor.bicep) loads the generated file at
// deploy time via loadJsonContent(), so refreshing the allowlist is a pure GitOps
// operation: run `npm run update-isp-allowlist`, commit, and redeploy.
//
// Scope: Dutch consumer ISPs Ziggo, KPN and Odido. Add/adjust ASNs in ISP_ASNS below.

import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT = resolve(__dirname, '..', 'config', 'isp-allowlist.json');

// Primary ASNs for each ISP. The first is the main consumer network.
const ISP_ASNS = {
  kpn: [1136, 286],
  ziggo: [33915, 9143],
  odido: [50266, 13127, 20507],
};

// Cap per provider to stay well under the Front Door WAF limit of 600 match
// values per condition (one Allow rule per provider).
const MAX_PER_PROVIDER = 600;

async function announcedPrefixes(asn) {
  const url = `https://stat.ripe.net/data/announced-prefixes/data.json?resource=AS${asn}`;
  const res = await fetch(url, { headers: { 'User-Agent': 'dc-opportunities-isp-allowlist' } });
  if (!res.ok) throw new Error(`RIPEstat AS${asn} -> HTTP ${res.status}`);
  const json = await res.json();
  return (json?.data?.prefixes ?? []).map((p) => p.prefix).filter(Boolean);
}

function dedupeSorted(list) {
  return [...new Set(list)].sort((a, b) => a.localeCompare(b));
}

// Convert an IPv4/IPv6 CIDR to a [start, end] BigInt range.
function cidrToRange(cidr) {
  const [addr, prefixStr] = cidr.split('/');
  const prefix = Number(prefixStr);
  const v6 = addr.includes(':');
  const bits = v6 ? 128n : 32n;
  let value;
  if (v6) {
    // Expand :: and parse hextets.
    const [head, tail] = addr.split('::');
    const headParts = head ? head.split(':') : [];
    const tailParts = tail ? tail.split(':') : [];
    const missing = 8 - headParts.length - tailParts.length;
    const parts = [...headParts, ...Array(Math.max(missing, 0)).fill('0'), ...tailParts];
    value = parts.reduce((acc, h) => (acc << 16n) + BigInt(parseInt(h || '0', 16)), 0n);
  } else {
    value = addr.split('.').reduce((acc, o) => (acc << 8n) + BigInt(Number(o)), 0n);
  }
  const hostBits = bits - BigInt(prefix);
  const start = (value >> hostBits) << hostBits;
  const end = start + (1n << hostBits) - 1n;
  return { start, end };
}

// Front Door WAF rejects overlapping IPMatch values. With aligned CIDRs, any two
// prefixes are either disjoint or one fully contains the other, so we drop every
// CIDR that is contained within a broader one from the same family.
function removeOverlaps(list) {
  const ranges = list.map((cidr) => ({ cidr, ...cidrToRange(cidr) }));
  return ranges
    .filter(
      (c) =>
        !ranges.some(
          (o) => o.cidr !== c.cidr && o.start <= c.start && o.end >= c.end && (o.end - o.start) > (c.end - c.start),
        ),
    )
    .map((c) => c.cidr);
}

async function collect(provider) {
  const asns = ISP_ASNS[provider];
  const all = [];
  for (const asn of asns) {
    const prefixes = await announcedPrefixes(asn);
    all.push(...prefixes);
    // Be gentle with the public API.
    await new Promise((r) => setTimeout(r, 300));
  }
  const unique = removeOverlaps(dedupeSorted(all));
  if (unique.length > MAX_PER_PROVIDER) {
    throw new Error(
      `${provider} has ${unique.length} prefixes, exceeds Front Door WAF cap of ${MAX_PER_PROVIDER}. ` +
        `Split into multiple Allow rules in frontdoor.bicep before proceeding.`,
    );
  }
  return unique;
}

async function main() {
  const providers = {};
  for (const provider of Object.keys(ISP_ASNS)) {
    // eslint-disable-next-line no-await-in-loop
    providers[provider] = await collect(provider);
  }

  const doc = {
    _comment:
      'AUTO-GENERATED by scripts/update-isp-allowlist.mjs. Do not edit by hand. ' +
      'Consumed at deploy time by infra/modules/frontdoor.bicep (loadJsonContent).',
    generatedUtc: new Date().toISOString(),
    source: 'RIPEstat announced-prefixes',
    asns: ISP_ASNS,
    counts: Object.fromEntries(Object.entries(providers).map(([k, v]) => [k, v.length])),
    kpn: providers.kpn,
    ziggo: providers.ziggo,
    odido: providers.odido,
  };

  await writeFile(OUT, `${JSON.stringify(doc, null, 2)}\n`, 'utf8');
  console.log(`Wrote ${OUT}`);
  for (const [k, v] of Object.entries(providers)) console.log(`  ${k}: ${v.length} prefixes`);
}

main().catch((err) => {
  console.error(err.message || err);
  process.exit(1);
});
